wp:postmeta.wp:meta_value:
[{"id":"39e98dc0","elType":"section","settings":{"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"130","left":0,"isLinked":false},"margin_laptop":{"unit":"px","top":"0","right":0,"bottom":"100","left":0,"isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":0,"bottom":"80","left":0,"isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":0,"bottom":"70","left":0,"isLinked":false},"background_background":"gradient"},"elements":[{"id":"35b55811","elType":"column","settings":{"_column_size":50,"_inline_size":null,"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_inline_size_tablet":100,"content_position_laptop":"center"},"elements":[{"id":"42caa4fb","elType":"widget","settings":{"image":{"url":"https://saraadusefoundation.org/wp-content/uploads/2025/02/RZ_SAF_D_1080x1920_ePanel_Outline-scaled.jpg","id":13850,"alt":"","source":"library","size":""},"image_size":"full","link_to":"custom","link":{"url":"#","is_external":"","nofollow":"","custom_attributes":""},"align_tablet":"center"},"elements":[],"widgetType":"image"}],"isInner":false},{"id":"26b21b91","elType":"column","settings":{"_column_size":50,"_inline_size":null,"background_background":"classic","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"80","isLinked":false},"padding_tablet":{"unit":"px","top":"30","right":"0","bottom":"0","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"","right":"","bottom":"","left":"","isLinked":false},"space_between_widgets":0,"_inline_size_tablet":100,"padding_laptop":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"padding_tablet_extra":{"unit":"em","top":"0","right":"3","bottom":"0","left":"2","isLinked":false},"padding_mobile_extra":{"unit":"em","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_widescreen":{"unit":"em","top":"2","right":"5","bottom":"2","left":"4","isLinked":false},"content_position":"center","css_classes":"about_cms_block"},"elements":[{"id":"9782144","elType":"widget","settings":{"title":"<b>Gemeinsam gegen weibliche Genitalverstümmelung</b>","header_size":"h3","typography_font_weight":"500","typography_text_transform":"uppercase","_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"heading"},{"id":"199e36be","elType":"widget","settings":{"editor":"<p>Anlässlich des internationalen Tag gegen die weibliche Genitalverstümmelung (engl.: Intertnational Day of Zero Tolerance to Female Genital Mutilation), der jährlich am 6. Februar statt findet, beleuchtet die Sara Aduse Foundation die Situation in der Schweiz und ruft mit ihrer Petiton #StopMädchenbeschneidung den Bund, die Kantone und die Bevölkerung zum Handeln auf. Die wichtigsten Informationen dazu sind in diesem Beitrag.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"70afbf53","elType":"widget","settings":{"text":"Zur Petition","_margin":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"link":{"url":"https://act.campax.org/petitions/stop-madchenbeschneidung-fur-gesunde-selbstbewusste-und-freie-frauen","is_external":"","nofollow":"","custom_attributes":""},"align":"center","background_color":"#55283C"},"elements":[],"widgetType":"button"},{"id":"251ae95","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3bc3c8e","elType":"widget","settings":{"title":"<b>Begriffsklärung und Verbreitung weiblicher Genitalverstümmelung</b>","header_size":"h3","typography_font_weight":"500","typography_text_transform":"uppercase","_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"heading"},{"id":"502c73d","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Weibliche Genitalverstümmelung (Female Genital Mutilation, kurz FGM) bezeichnet die teilweise oder vollständige Entfernung der äusseren weiblichen Genitalien ohne medizinischen Grund. Diese Praxis verursacht lebenslange körperliche und psychische Leiden und ist eine Menschenrechtsverletzung. Mit der Zuwanderung ist diese archaische Praxis auch in die Schweiz gelangt. Junge Mädchen werden von sogenannten Beschneiderinnen mit einer Rasierklinge oder einem anderen scharfen Instrument verstümmelt. In vielen Fällen wird den Mädchen die Klitoris entfernt, manchmal auch die inneren und äusseren Schamlippen. Die schwerste Form dieser Praxis ist das Zunähen der Vagina, wobei nur eine winzige Öffnung bleibt, durch die Urin und Menstruationsblut tröpfchenweise abfliessen. Ein normales Sexualleben ist danach nicht mehr möglich, was eines der Hauptziele dieser grausamen Tradition ist.</span></p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"35aae1dd","elType":"section","settings":{"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"130","left":0,"isLinked":false},"margin_laptop":{"unit":"px","top":"0","right":0,"bottom":"100","left":0,"isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":0,"bottom":"80","left":0,"isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":0,"bottom":"70","left":0,"isLinked":false}},"elements":[{"id":"27ab8d15","elType":"column","settings":{"_column_size":50,"_inline_size":null,"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_inline_size_tablet":100,"content_position_laptop":"center"},"elements":[{"id":"cae25e5","elType":"widget","settings":{"editor":"<h3><strong>FGM in der Schweiz</strong></h3><p>Seit 2012 ist FGM in der Schweiz ein Offizialdelikt <a href="https://www.fedlex.admin.ch/eli/cc/54/757_781_799/de#art_124">(Art.124 StGB),</a> das von den Behörden automatisch verfolgt wird. In der Schweiz kam es bislang nur zu einer einzigen Verurteilung (im Kanton Neuenburg). Gleichzeitig ist die Anzahl der betroffenen und gefährdeten Personen gestiegen: Laut dem <a href="https://www.bag.admin.ch/bag/de/home/strategie-und-politik/nationale-gesundheitsstrategien/gesundheitliche-chancengleichheit/chancengleichheit-in-der-gesundheitsversorgung/massnahmen-gegen-weibliche-genitalverstuemmelung.html">Bundesamt für Gesundheit</a> sind inzwischen rund 24’600 Frauen und Mädchen in der Schweiz betroffen oder gefährdet.</p><p><span style="background-color: transparent; color: var(--global-palette5); font-family: var(--global-body-font-family);">Die betroffenen Frauen stammen oft aus Afrika, insbesondere aus Somalia, Äthiopien und dem Sudan. Viele leiden ihr Leben lang unter chronischen Schmerzen, die oft nur durch eine operative Korrektur gemildert werden können. Wo genau die Verstümmelungen erfolgen – im Heimatland, im Ausland oder sogar in der Schweiz – bleibt häufig unklar.</span></p><p>In der Schweiz kommen viele Ärztinnen und Ärzte in ihrem Alltag mit Opfern von weiblicher Genitalverstümmelung in Kontakt. Schon 2012 gaben <a href="https://www.bag.admin.ch/dam/bag/de/dokumente/nat-gesundheitsstrategien/nat-programm-migration-und-gesundheit/chancengleichheit-in-der-gesundheitsversorgung/massnahmen-gegen-weibliche-genitalverstuemmelung/studien/unicef-umfrage-2012-genitalverst.pdf.download.pdf/unicef-umfrage-2012-genitalverst.pdf">40 Prozent des befragten medizinischen Personal</a>s an, dass sie bereits Patientinnen mit FGM gesehen haben.</p><p>Hierzulande wurden bereits wichtige Fortschritte erzielt. Ein entscheidender Schritt war u.a. das <a href="https://www.parlament.ch/de/ratsbetrieb/suche-curia-vista/geschaeft?AffairId=20183551">Postulat von Natalie Rickl</a>i im Jahr 2018, welches dem Thema politische Beachtung verschaffte. Infolgedessen wurden auf kantonaler Ebene Anlaufstellen für betroffene Frauen geschaffen, die ihnen <a href="https://www.parlament.ch/centers/eparl/curia/2018/20183551/Bericht%20BR%20D.pdf">Beratung und Unterstützung bieten.</a></p>"},"elements":[],"widgetType":"text-editor"},{"id":"18086ff","elType":"widget","settings":{"text":"Zur Petition!","_margin":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"align":"center","link":{"url":"https://act.campax.org/petitions/stop-madchenbeschneidung-fur-gesunde-selbstbewusste-und-freie-frauen","is_external":"","nofollow":"","custom_attributes":""},"button_text_color":"#FFFFFF","background_color":"#55283C"},"elements":[],"widgetType":"button"}],"isInner":false},{"id":"39763b63","elType":"column","settings":{"_column_size":50,"_inline_size":null,"background_background":"classic","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"80","isLinked":false},"padding_tablet":{"unit":"px","top":"30","right":"0","bottom":"0","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"","right":"","bottom":"","left":"","isLinked":false},"space_between_widgets":0,"_inline_size_tablet":100,"padding_laptop":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"padding_tablet_extra":{"unit":"em","top":"0","right":"3","bottom":"0","left":"2","isLinked":false},"padding_mobile_extra":{"unit":"em","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_widescreen":{"unit":"em","top":"2","right":"5","bottom":"2","left":"4","isLinked":false},"content_position":"center","css_classes":"about_cms_block"},"elements":[{"id":"871e0ee","elType":"widget","settings":{"video_type":"hosted","youtube_url":"https://www.youtube.com/watch?v=XHOmBV4js_E","vimeo_url":"https://vimeo.com/235215203","dailymotion_url":"https://www.dailymotion.com/video/x6tqhqb","hosted_url":{"url":"https://saraadusefoundation.org/wp-content/uploads/2025/02/1080-stop_maedchenbeschneidung_-_fuer_selbstbewusste_freie_und_gesunde_frauen-2160p-1-2.mov","id":13884,"size":"","alt":"","source":"library"},"videopress_url":"https://videopress.com/v/ZCAOzTNk","autoplay":"yes","play_on_mobile":"yes","mute":"yes","aspect_ratio":"916"},"elements":[],"widgetType":"video"}],"isInner":false}],"isInner":false},{"id":"636ecd1f","elType":"section","settings":{"structure":"20","margin":{"unit":"px","top":"0","right":0,"bottom":"130","left":0,"isLinked":false},"margin_laptop":{"unit":"px","top":"0","right":0,"bottom":"100","left":0,"isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":0,"bottom":"80","left":0,"isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":0,"bottom":"70","left":0,"isLinked":false},"background_background":"gradient"},"elements":[{"id":"4bac1624","elType":"column","settings":{"_column_size":50,"_inline_size":null,"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_inline_size_tablet":100,"content_position_laptop":"center"},"elements":[{"id":"15b3d9b8","elType":"widget","settings":{"image":{"url":"https://saraadusefoundation.org/wp-content/uploads/2025/02/Design-ohne-Titel-17.png","id":13843,"alt":"","source":"library","size":""},"image_size":"full","link_to":"custom","link":{"url":"#","is_external":"","nofollow":"","custom_attributes":""},"align_tablet":"center"},"elements":[],"widgetType":"image"}],"isInner":false},{"id":"4bd15be4","elType":"column","settings":{"_column_size":50,"_inline_size":null,"background_background":"classic","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"80","isLinked":false},"padding_tablet":{"unit":"px","top":"30","right":"0","bottom":"0","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"","right":"","bottom":"","left":"","isLinked":false},"space_between_widgets":0,"_inline_size_tablet":100,"padding_laptop":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"padding_tablet_extra":{"unit":"em","top":"0","right":"3","bottom":"0","left":"2","isLinked":false},"padding_mobile_extra":{"unit":"em","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_widescreen":{"unit":"em","top":"2","right":"5","bottom":"2","left":"4","isLinked":false},"content_position":"center","css_classes":"about_cms_block"},"elements":[{"id":"ce0f57c","elType":"widget","settings":{"title":"<b>Interkulturelle Zusammenarbeit mit Anlaufstellen</b>","header_size":"h3","typography_font_weight":"500","typography_text_transform":"uppercase","_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"heading"},{"id":"40434f8a","elType":"widget","settings":{"editor":"<p>Es ist entscheidend, mit Menschen zusammenzuarbeiten, die aus denselben Kulturkreisen stammen. Nur so kann Vertrauen aufgebaut und ein ehrlicher Dialog mit den Betroffenen gefördert werden. Viele beschnittene Frauen sind traumatisiert und benötigen sensible Unterstützung. Dieser Umgang erfordert Einfühlungsvermögen, kulturelles Verständnis und Fachwissen. Gegenseitiges Verständnis ist essentiell, um eine vertrauensvolle Beziehung aufzubauen und einen niederschwelligen Zugang für betroffene Frauen und Mädchen zu ermöglichen und die Präventionsarbeit zu intensivieren.</p><p><strong>Aufklärung im eigenen Kulturkreis</strong><br />Auch Frauen und Männer, die nicht direkt von FGM betroffen sind, aber aus denselbem Kulturkreis stammen, müssen in diesem Kontext angesprochen werden. So kann die Beschneidungspraxis im engen Kontakt mit Betroffenen und ihrem kulturellen Umfeld verhindert werden. Menschen aus diesen Kulturkreisen, die in der Schweiz aufgewachsen sind und nicht von FGM betroffen sind, bilden eine Brücke zwischen der hiesigen und ausländischen Kulturen, da sie beide Seiten kennen und so aufklärend gegen weibliche Genitalverstümmelung vorgehen können.</p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"2efcda7","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":0,"column":"0","row":"0"}},"elements":[{"id":"4468180","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":54.743},"_flex_size":"none","_element_width":"initial"},"elements":[{"id":"eabe57a","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Petition Box</title>
<style>
.petition-box {
max-width: 400px;
padding: 20px;
background-color: #55283c; /* Hintergrundfarbe der Box */
color: white; /* Textfarbe */
text-align: center;
border-radius: 12px;
box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
font-family: Arial, sans-serif;
margin: 50px auto;
}
.petition-box h2 {
font-size: 24px;
margin-bottom: 10px;
}
.petition-box p {
font-size: 16px;
margin-bottom: 15px;
}
.petition-box a {
display: inline-block;
background-color: white; /* Button-Hintergrundfarbe */
color: #b65525; /* Button-Textfarbe */
padding: 12px 20px;
font-size: 16px;
font-weight: bold;
text-decoration: none;
border-radius: 8px;
transition: background 0.3s ease, transform 0.2s ease;
}
.petition-box a:hover {
background-color: #b65525; /* Hover-Farbe */
color: white; /* Textfarbe im Hover-Zustand */
transform: scale(1.05);
}
</style>
</head>
<body>
<div class="petition-box">
<h2>Forderung: Verstärkte Umsetzung der Aufklärungs- und Präventionsmassnahmen</h2>
<p>
Um diese grausame Praxis zu beenden, haben wir die Petition #StopMädchenbeschneidung ins Leben gerufen. Wir fordern die kantonale Gesundheitsdirektorenkonferenz auf, die Aufklärungs- und Präventionsmassnahmen für betroffene Frauen und Mädchen verstärkter umzusetzen.
<br>
</p>
<a href="https://act.campax.org/petitions/stop-madchenbeschneidung-fur-gesunde-selbstbewusste-und-freie-frauen" target="_blank">Jetzt unterzeichnen</a>
</div>
</body>
</html>","_element_width":"initial","_element_custom_width":{"unit":"%","size":130.19},"_flex_size":"none"},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"a3caff9","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":49.963},"_flex_size":"none","_element_width":"initial"},"elements":[{"id":"9b0114f","elType":"widget","settings":{"editor":"<p><strong>Von FGM betroffene Frauen als Personal in Anlaufstellen</strong><br />Ein Teil des Personals in Anlaufstellen sollte aus Frauen bestehen, die selbst von FGM betroffen sind und in der Schweiz aufgewachsen sind. Durch diese kulturelle Nähe würde die Hemmschwelle für betroffene Frauen sinken, sich an die Anlaufstelle zu wenden. Zudem könnte sich diese Information in den entsprechenden migrantischen Communities verbreiten und zur Aufklärung beitragen.</p><p><strong>Informations- und Sensibilisierungsbedarf bei Fachpersonen</strong><br />Fachpersonen und Institutionen die mit Kindern arbeiten, müssen besser geschult werden bezüglich Melderechten und Meldepflichten bei Verdachtsfällen auf weibliche Genitalverstümmelung.</p><p><strong>Aufnahme des Thema FGM in Lehrplänen</strong><br />Das Thema FGM muss verpflichtend in die Lehrpläne von Medizinstudenten, Gynäkologen, Hebammen, Pflegefachkräften, Sozialarbeitern und Lehrkräften aufgenommen werden, um die Anzahl betroffener und gefährdeter Personen langfristig zu senken.</p>"},"elements":[],"widgetType":"text-editor"}],"isInner":true}],"isInner":false},{"id":"d496f22","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"3c804f1","elType":"widget","settings":{"editor":"<p><strong>Herzlichen Dank für deine Unterstützung!</strong></p>","align":"center"},"elements":[],"widgetType":"text-editor"},{"id":"7152d0d","elType":"widget","settings":{"text":"Unterzeichne jetzt unsere Petition","_margin":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_laptop":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"align":"center","link":{"url":"https://act.campax.org/petitions/stop-madchenbeschneidung-fur-gesunde-selbstbewusste-und-freie-frauen","is_external":"","nofollow":"","custom_attributes":""},"button_text_color":"#FFFFFF","background_color":"#55283C"},"elements":[],"widgetType":"button"}],"isInner":false},{"id":"a276b6c","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"40c48af","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"}],"isInner":false},{"id":"1be7c327","elType":"section","settings":{"margin":{"unit":"px","top":"10","right":0,"bottom":"130","left":0,"isLinked":false},"html_tag":"div","structure":"30","margin_laptop":{"unit":"px","top":"10","right":0,"bottom":"100","left":0,"isLinked":false},"margin_tablet":{"unit":"px","top":"10","right":0,"bottom":"80","left":0,"isLinked":false},"margin_mobile":{"unit":"px","top":"10","right":0,"bottom":"70","left":0,"isLinked":false}},"elements":[{"id":"1a66ea4f","elType":"column","settings":{"_column_size":33,"_inline_size":null,"padding":{"unit":"px","top":"0","right":"15","bottom":"0","left":"15","isLinked":false},"space_between_widgets":0,"padding_tablet":{"unit":"px","top":"0","right":"10","bottom":"0","left":"10","isLinked":false},"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"10","left":"0","isLinked":false},"css_classes":"cmsblock"},"elements":[{"id":"54905e04","elType":"widget","settings":{"image":{"url":"https://bozatote.myhostpoint.ch/wp-content/uploads/2024/09/1-4.png","id":12301,"alt":"","source":"library","size":""},"image_size":"full","background_hover_transition":{"unit":"px","size":0.3,"sizes":[]},"_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"image"},{"id":"21a261ef","elType":"widget","settings":{"space":{"uni